import{_ as i,a0 as n,w as s,s as p,ao as l,I as o,x as e,a1 as d,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const j=JSON.parse('{"title":"Fedora 28 服務器版的模組化 | LCTT x X-CMD","titleTemplate":false,"description":"Fedora 28 服務器版的模組化 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora 28 服務器版的模組化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora 28 服務器版的模組化 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180507 Modularity in Fedora 28 Server Edition","title":"Fedora 28 服務器版的模組化","tag":"201901","desc":""},"relativePath":"201901/20180507 Modularity in Fedora 28 Server Edition.md","filePath":"[post].md"}'),u={name:"201901/20180507 Modularity in Fedora 28 Server Edition.md"};function f(F,r,m,x,g,T){const a=n("Link");return s(),p("div",null,[r[25]||(r[25]=l('<h1 id="fedora-28-服務器版的模組化" tabindex="-1">Fedora 28 服務器版的模組化 <a class="header-anchor" href="#fedora-28-服務器版的模組化" aria-label="Permalink to “Fedora 28 服務器版的模組化”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/05/f28-server-modularity-1024x433.jpg" alt=""></p><h3 id="什麼是模組化" tabindex="-1">什麼是模組化 <a class="header-anchor" href="#什麼是模組化" aria-label="Permalink to “什麼是模組化”">​</a></h3><p>所有開源發行版都面臨的一個經典難題是“太快/太慢”的問題。用户安裝操作系統是為了能夠使用其應用程序。像 Fedora 這樣的全面的發行版在大量可用軟件方面有其優勢和劣勢。雖然有用户想要的軟件包，但可能無法使用其所需的版本。以下是<ruby>模組化<rt>Modularity</rt></ruby>如何幫助解決該問題。</p><p>對於某些用户，Fedora 有時升級得太快。其快速發佈週期以及儘可能提供最新穩定軟件的願望可能導致與應用程序的兼容性下降。如果因為 Fedora 將 Web 框架升級為不兼容的版本而導致用户無法運行 Web 應用程序，則會非常令人沮喪。對“太快”問題的經典回答是“Fedora 應該有一個 LTS 版本。”然而，這種方法只能解決問題的一半，並使這個難題的另一面變得更糟。</p>',5)),o("p",null,[r[1]||(r[1]=e("有時候 Fedora 對某些用户而言又升級速度太慢。例如，Fedora 的發佈可能與其它想要的軟件的發佈時間不匹配。一旦 Fedora 版本宣佈穩定，打包者必須遵守 ",-1)),d(a,{href:"https://fedoraproject.org/wiki/Updates_Policy#Stable_Releases"},{default:t(()=>[...r[0]||(r[0]=[e("穩定更新政策",-1)])]),_:1}),r[2]||(r[2]=e(" 並且不能在系統中引入不兼容的更改。",-1))]),r[26]||(r[26]=o("p",null,"Fedora 的模組化從兩個方面解決了這個問題。Fedora 仍將根據其傳統政策發佈標準版本。但是，它還將提供一組模組給出流行軟件的限定替代版本。那些處於“太快”陣營的人仍然可以享受 Fedora 的新內核和其它通用平台增強功能。此外，他們仍然可以訪問支持其應用程序的舊框架或工具鏈。",-1)),r[27]||(r[27]=o("p",null,"此外，那些喜歡更新潮一些的用户可以訪問比發佈時更新的軟件。",-1)),r[28]||(r[28]=o("h3",{id:"模組化不是什麼",tabindex:"-1"},[e("模組化不是什麼？ "),o("a",{class:"header-anchor",href:"#模組化不是什麼","aria-label":"Permalink to “模組化不是什麼？”"},"​")],-1)),o("p",null,[r[5]||(r[5]=e("模組化不是 ",-1)),o("ruby",null,[d(a,{href:"https://www.softwarecollections.org/"},{default:t(()=>[...r[3]||(r[3]=[e("軟件集合",-1)])]),_:1}),r[4]||(r[4]=o("rt",null,"Software Collections",-1))]),r[6]||(r[6]=e(" 的直接替代品。這兩種技術試圖解決許多相同的問題，但有明顯的差異。",-1))]),r[29]||(r[29]=l('<p>軟件集合可以在系統上並行安裝不同版本的軟件包。但是，它們的缺點是每份安裝包都存在於文件系統上的它們自己的命名空間裏面。此外，需要告訴每個依賴它們的應用程序在哪裏找到它們。</p><p>使用模組化，系統上只存在一個版本的軟件包，但用户可以選擇哪個版本。優點是該版本位於系統的標準位置。該程序包不需要對依賴它的應用程序進行特殊更改。來自用户研究的反饋表明，大多數用户實際上並不依賴於並行安裝。容器化和虛擬化解決了這個問題。</p><h3 id="為什麼不乾脆使用容器化" tabindex="-1">為什麼不乾脆使用容器化？ <a class="header-anchor" href="#為什麼不乾脆使用容器化" aria-label="Permalink to “為什麼不乾脆使用容器化？”">​</a></h3><p>這是另一個常見問題。為什麼用户在可以使用容器時還需要模組？答案是，人們仍然需要維護容器中的軟件。 模組為那些用户不需要自己維護、更新和修補的容器提供預打包的內容。這就是 Fedora 如何利用發行版的傳統價值並將其轉移到新的容器化的世界。</p><p>以下是模組化如何為 Node.js 和 Review Board 的用户解決問題的示例。</p><h3 id="node-js" tabindex="-1">Node.js <a class="header-anchor" href="#node-js" aria-label="Permalink to “Node.js”">​</a></h3><p>許多讀者可能熟悉 Node.js，這是一個流行的服務器端 JavaScript 運行時環境。Node.js 採用偶數/奇數版本策略。它的社區支持偶數版本（6.x、8.x、10.x 等）約 30 個月。同時，他們也支持奇數版本，基本上是 9 個月的開發者預覽版。</p><p>由於這個週期的原因，Fedora 在其穩定的倉庫中只攜帶最新的偶數版本的 Node.js。它完全避免了奇數版本，因為它們的生命週期比 Fedora 短，並且通常與 Fedora 發佈週期不一致。對於一些希望獲得最新和最大增強功能的 Fedora 用户來説，這並不合適。</p><p>由於模組化，Fedora 28 不是提供了一個版本，而是提供了三個版本的 Node.js，以滿足開發人員和穩定部署的需求。Fedora 28 的傳統倉庫帶有 Node.js 8.x。此版本是發佈時最新的長期穩定版本。模組倉庫（默認情況下在 Fedora 28 Server 版本上可用）也使得更舊的 Node.js 6.x 版本和更新的 Node.js 9.x 開發版本可用。</p>',9)),o("p",null,[r[8]||(r[8]=e("另外，Node.js 在 Fedora 28 之後幾天發佈了 10.x 上游版本。過去，想要部署該版本的用户必須等到 Fedora 29，或者使用來自 Fedora 之外的源代碼。但是，再次感謝模組化，Node.js 10.x 已經在 Fedora 28 的 Modular Updates-Testing 倉庫中 ",-1)),d(a,{href:"https://bodhi.fedoraproject.org/updates/FEDORA-MODULAR-2018-2b0846cb86"},{default:t(()=>[...r[7]||(r[7]=[e("可用",-1)])]),_:1}),r[9]||(r[9]=e(" 了。",-1))]),r[30]||(r[30]=o("h3",{id:"review-board",tabindex:"-1"},[e("Review Board "),o("a",{class:"header-anchor",href:"#review-board","aria-label":"Permalink to “Review Board”"},"​")],-1)),r[31]||(r[31]=o("p",null,"Review Board 是一個流行的 Django 應用程序，用於執行代碼審查。Fedora 從 Fedora 13 到 Fedora 21 都包括了 Review Board。此時，Fedora 轉移到了 Django 1.7。由於 Django 資料庫支持的向後兼容性在不斷變化，而 Review Board 無法跟上。它在 RHEL / CentOS 7 的 EPEL 倉庫中仍然存在，而僅僅是因為這些發行版的版本幸運地被凍結在 Django 1.6上。儘管如此，它在 Fedora 的時代顯然已經過去了。",-1)),r[32]||(r[32]=o("p",null,"然而，隨着模組化的出現，Fedora 能夠再次將舊的 Django 作為非默認模組流發佈。因此，Review Board 已作為一個模組在 Fedora 上恢復了。Fedora 承載了來自上游的兩個受支持的版本：2.5.x 和 3.0.x。",-1)),r[33]||(r[33]=o("h3",{id:"組合在一起",tabindex:"-1"},[e("組合在一起 "),o("a",{class:"header-anchor",href:"#組合在一起","aria-label":"Permalink to “組合在一起”"},"​")],-1)),r[34]||(r[34]=o("p",null,"Fedora 一直為用户提供非常廣泛的軟件使用。Fedora 模組化現在為他們所需的軟件版本提供了更深入的選擇。接下來的幾年對於 Fedora 來説將是非常令人興奮的，因為開發人員和用户可以以新的和令人興奮的（或舊的和令人興奮的）方式組合他們的軟件。",-1)),r[35]||(r[35]=o("hr",null,null,-1)),o("p",null,[r[11]||(r[11]=e("via: ",-1)),d(a,{href:"https://fedoramagazine.org/working-modules-fedora-28/"},{default:t(()=>[...r[10]||(r[10]=[e("https://fedoramagazine.org/working-modules-fedora-28/",-1)])]),_:1})]),o("p",null,[r[16]||(r[16]=e("作者：",-1)),d(a,{href:"https://fedoramagazine.org/author/sgallagh/"},{default:t(()=>[...r[12]||(r[12]=[e("Stephen Gallagher",-1)])]),_:1}),r[17]||(r[17]=e(" 選題：",-1)),d(a,{href:"https://github.com/wxy"},{default:t(()=>[...r[13]||(r[13]=[e("wxy",-1)])]),_:1}),r[18]||(r[18]=e(" 譯者：",-1)),d(a,{href:"https://github.com/wxy"},{default:t(()=>[...r[14]||(r[14]=[e("wxy",-1)])]),_:1}),r[19]||(r[19]=e(" 校對：",-1)),d(a,{href:"https://github.com/wxy"},{default:t(()=>[...r[15]||(r[15]=[e("wxy",-1)])]),_:1})]),o("p",null,[r[22]||(r[22]=e("本文由 ",-1)),d(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...r[20]||(r[20]=[e("LCTT",-1)])]),_:1}),r[23]||(r[23]=e(" 原創編譯，",-1)),d(a,{href:"https://linux.cn/"},{default:t(()=>[...r[21]||(r[21]=[e("Linux中國",-1)])]),_:1}),r[24]||(r[24]=e(" 榮譽推出",-1))])])}const v=i(u,[["render",f]]);export{j as __pageData,v as default};
